import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  Alert,
  alpha,
  Box,
  Button,
  Chip,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormHelperText,
  Grid,
  IconButton,
  Paper,
  Stack,
  TextField,
  Typography,
  useMediaQuery,
  useTheme,
} from "@mui/material";
import {
  ArrowBack,
  ArrowForward,
  CameraAlt,
  CheckCircle,
  Close,
  CloudUploadOutlined,
  Email,
  HomeWorkOutlined,
  LocationOn,
  MyLocation,
  Phone,
  Tag,
  WhatsApp,
} from "@mui/icons-material";
import L from "leaflet";
import { useLocation, useNavigate } from "react-router-dom";
import { MapContainer, Marker, TileLayer, useMap, useMapEvents } from "react-leaflet";
import "leaflet/dist/leaflet.css";

delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: "https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon-2x.png",
  iconUrl: "https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon.png",
  shadowUrl: "https://unpkg.com/leaflet@1.9.4/dist/images/marker-shadow.png",
});

const BASE_URL = "http://localhost:9001/api/v1";
const PRIMARY = "#e8703a";
const PRIMARY_DARK = "#d05e2a";
const SURFACE = "#ffffff";
const SURFACE_ALT = "#f0f2f5";
const BORDER = "#e5e7eb";
const TEXT = "#1a1a1a";
const TEXT_SUB = "#555";
const TEXT_MUTED = "#888";
const ERROR_COLOR = "#e53935";
const SUCCESS = "#16a34a";
const ALLOWED_IMAGE_TYPES = ["image/jpeg", "image/png", "image/webp", "image/heic", "image/heif"];
const DEFAULT_CENTER = [20.5937, 78.9629];

const ROOF_TYPES = ["Flat Roof", "Sloped Roof", "Metal Roof", "Tile Roof", "Concrete Roof"];
const ROOF_MATERIALS = ["Concrete", "Metal Sheet", "Tile", "Asphalt", "Wood"];
const ROOF_CONDITIONS = ["Excellent", "Good", "Fair", "Poor", "Needs Repair"];
const SHADING_OPTIONS = ["Trees", "Buildings", "Water Tank", "Antenna/Satellite", "None"];
const SITE_ACCESS_OPTIONS = ["Easy", "Moderate", "Difficult", "Very Difficult"];
const EARTHING_OPTIONS = ["Yes", "No", "Needs Upgrade"];
const PHASE_OPTIONS = ["Single Phase", "Three Phase"];
const PANEL_BRANDS = ["Waaree", "Adani", "Tata Power", "Vikram Solar", "Renewsys"];
const INVERTER_BRANDS = ["Growatt", "SMA", "Fronius", "Sungrow", "Huawei"];
const INVERTER_TYPES = ["String Inverter", "Microinverter", "Hybrid Inverter"];

const getToken = () =>
  localStorage.getItem("token") ||
  localStorage.getItem("authToken") ||
  localStorage.getItem("accessToken") ||
  "";

const getLeadFullName = (lead) => [lead?.firstName, lead?.lastName].filter(Boolean).join(" ").trim();

const makeInitialSurveyData = (lead) => ({
  roofType: "",
  roofMaterial: "",
  roofCondition: "",
  shadingIssues: [],
  siteAccess: "",
  existingElectricalLoad: "",
  mainDistributionBoardLocation: "",
  earthingAvailable: "",
  phaseType: "",
  recommendedPanelBrand: "",
  recommendedInverterBrand: "",
  inverterType: "",
  availableRoofArea: "",
  usableRoofArea: "",
  distanceFromRoofToDb: "",
  customerExpectations: "",
  specialRequirements: "",
  challengesConcerns: "",
  locationName: lead?.companyName || getLeadFullName(lead) || lead?.address || "",
  latitude: "",
  longitude: "",
  remarks: "",
});

function MapViewportSync({ center }) {
  const map = useMap();

  useEffect(() => {
    if (!center) return;
    map.setView(center, 16, { animate: true });
  }, [center, map]);

  return null;
}

function MapClickHandler({ onPick }) {
  useMapEvents({
    click(event) {
      onPick(event.latlng.lat, event.latlng.lng);
    },
  });

  return null;
}

function UploadPreview({ photo, onRemove }) {
  return (
    <Box
      sx={{
        position: "relative",
        width: 90,
        height: 90,
        borderRadius: 2,
        overflow: "hidden",
        border: `1px solid ${BORDER}`,
        flexShrink: 0,
      }}
    >
      <Box component="img" src={photo.preview} alt={photo.file.name} sx={{ width: "100%", height: "100%", objectFit: "cover" }} />
      <IconButton
        size="small"
        onClick={() => onRemove(photo.id)}
        sx={{
          position: "absolute",
          top: 4,
          right: 4,
          width: 22,
          height: 22,
          bgcolor: "rgba(0,0,0,0.55)",
          color: "#fff",
          "&:hover": { bgcolor: "rgba(0,0,0,0.75)" },
        }}
      >
        <Close sx={{ fontSize: 14 }} />
      </IconButton>
    </Box>
  );
}

function SuccessDialog({ open, onClose, leadName }) {
  return (
    <Dialog open={open} onClose={onClose} maxWidth="xs" fullWidth>
      <DialogTitle sx={{ textAlign: "center", pt: 3.5 }}>
        <Box
          sx={{
            width: 72,
            height: 72,
            borderRadius: "50%",
            bgcolor: alpha(SUCCESS, 0.12),
            display: "grid",
            placeItems: "center",
            mx: "auto",
            mb: 2,
          }}
        >
          <CheckCircle sx={{ fontSize: 40, color: SUCCESS }} />
        </Box>
        <Typography variant="h6" sx={{ color: TEXT, fontWeight: 800 }}>
          Site Survey Saved
        </Typography>
        <Typography variant="body2" sx={{ color: TEXT_MUTED, mt: 1 }}>
          {leadName ? `Survey details for ${leadName} were saved successfully.` : "Survey details were saved successfully."}
        </Typography>
      </DialogTitle>
      <DialogActions sx={{ justifyContent: "center", pb: 3, px: 3 }}>
        <Button
          variant="contained"
          onClick={onClose}
          sx={{
            borderRadius: 2,
            px: 3,
            py: 1,
            bgcolor: PRIMARY,
            fontWeight: 700,
            textTransform: "none",
            "&:hover": { bgcolor: PRIMARY_DARK },
          }}
        >
          Close
        </Button>
      </DialogActions>
    </Dialog>
  );
}

export default function VisitDetails({ onClose, onSave }) {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));
  const navigate = useNavigate();
  const locationState = useLocation();
  const lead = locationState.state?.lead || null;

  const [currentStep, setCurrentStep] = useState(1);
  const [surveyData, setSurveyData] = useState(() => makeInitialSurveyData(lead));
  const [photos, setPhotos] = useState([]);
  const [validationErrors, setValidationErrors] = useState({});
  const [locationLoading, setLocationLoading] = useState(false);
  const [locationAttempts, setLocationAttempts] = useState(0);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [successOpen, setSuccessOpen] = useState(false);
  const [submittedVisit, setSubmittedVisit] = useState(null);
  const fileInputRef = useRef(null);

  const leadName = useMemo(() => getLeadFullName(lead) || lead?.companyName || "Site Survey", [lead]);
  const avatarLabel = useMemo(() => {
    const seed = leadName || "SS";
    return seed
      .split(" ")
      .filter(Boolean)
      .slice(0, 2)
      .map((part) => part[0]?.toLowerCase())
      .join("") || "ss";
  }, [leadName]);

  const mapCenter = useMemo(() => {
    if (surveyData.latitude && surveyData.longitude) {
      return [Number(surveyData.latitude), Number(surveyData.longitude)];
    }
    return DEFAULT_CENTER;
  }, [surveyData.latitude, surveyData.longitude]);

  const updateField = useCallback((field, value) => {
    setSurveyData((prev) => ({ ...prev, [field]: value }));
    setValidationErrors((prev) => ({ ...prev, [field]: "" }));
  }, []);

  const toggleCheckboxValue = useCallback((field, value) => {
    setSurveyData((prev) => {
      const current = prev[field] || [];
      const next = current.includes(value)
        ? current.filter((item) => item !== value)
        : value === "None"
        ? ["None"]
        : [...current.filter((item) => item !== "None"), value];
      return { ...prev, [field]: next };
    });
    setValidationErrors((prev) => ({ ...prev, [field]: "" }));
  }, []);

  const reverseGeocode = useCallback(async (lat, lng) => {
    try {
      const response = await fetch(
        `https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${lat}&lon=${lng}`,
        { headers: { Accept: "application/json" } },
      );
      if (!response.ok) return "";
      const data = await response.json();
      return data?.display_name || "";
    } catch {
      return "";
    }
  }, []);

  const applyCoordinates = useCallback(async (lat, lng, shouldPrefillLocation = true) => {
    updateField("latitude", Number(lat).toFixed(6));
    updateField("longitude", Number(lng).toFixed(6));

    if (shouldPrefillLocation && !surveyData.locationName.trim()) {
      const label = await reverseGeocode(lat, lng);
      if (label) updateField("locationName", label);
    }
  }, [reverseGeocode, surveyData.locationName, updateField]);

  const getCurrentLocation = useCallback((attempt = 0) => {
    if (!navigator.geolocation) {
      setError("Geolocation is not supported by this browser.");
      return;
    }

    setLocationLoading(true);
    setError("");

    navigator.geolocation.getCurrentPosition(
      async (position) => {
        await applyCoordinates(position.coords.latitude, position.coords.longitude, true);
        setLocationAttempts(0);
        setLocationLoading(false);
      },
      (geoError) => {
        if ((geoError.code === 3 || geoError.code === geoError.TIMEOUT) && attempt < 2) {
          const nextAttempt = attempt + 1;
          setLocationAttempts(nextAttempt);
          setTimeout(() => getCurrentLocation(nextAttempt), 1200);
          return;
        }
        setLocationLoading(false);
        setError(geoError.code === 1 ? "Location permission denied." : "Unable to capture current location.");
      },
      { enableHighAccuracy: true, timeout: 12000, maximumAge: 0 },
    );
  }, [applyCoordinates]);

  useEffect(() => {
    getCurrentLocation();
  }, [getCurrentLocation]);

  useEffect(() => {
    if (!lead) return;
    setSurveyData((prev) => ({
      ...prev,
      locationName: prev.locationName || lead.companyName || getLeadFullName(lead) || lead.address || "",
    }));
  }, [lead]);

  useEffect(() => {
    return () => {
      photos.forEach((photo) => URL.revokeObjectURL(photo.preview));
    };
  }, [photos]);

  const addFiles = useCallback((fileList) => {
    const picked = Array.from(fileList || []);
    if (!picked.length) return;

    const valid = [];
    let localError = "";

    picked.forEach((file) => {
      if (!ALLOWED_IMAGE_TYPES.includes(file.type)) {
        localError = "Only JPG, PNG, WEBP, HEIC, and HEIF images are supported.";
        return;
      }
      if (file.size > 10 * 1024 * 1024) {
        localError = "Each image must be under 10 MB.";
        return;
      }
      valid.push({
        id: `${file.name}-${file.lastModified}-${Math.random().toString(36).slice(2, 8)}`,
        file,
        preview: URL.createObjectURL(file),
      });
    });

    if (localError) setError(localError);
    if (valid.length) {
      setPhotos((prev) => [...prev, ...valid]);
      setValidationErrors((prev) => ({ ...prev, photos: "" }));
    }
  }, []);

  const handleFileChange = useCallback((event) => {
    addFiles(event.target.files);
    event.target.value = "";
  }, [addFiles]);

  const removePhoto = useCallback((photoId) => {
    setPhotos((prev) => {
      const target = prev.find((photo) => photo.id === photoId);
      if (target) URL.revokeObjectURL(target.preview);
      return prev.filter((photo) => photo.id !== photoId);
    });
  }, []);

  const handleMapPick = useCallback(async (lat, lng) => {
    await applyCoordinates(lat, lng, true);
  }, [applyCoordinates]);

  const validateStep = useCallback((step) => {
    const nextErrors = {};

    if (step === 1) {
      if (!surveyData.roofType) nextErrors.roofType = "Roof type is required.";
      if (!surveyData.roofMaterial) nextErrors.roofMaterial = "Roof material is required.";
      if (!surveyData.roofCondition) nextErrors.roofCondition = "Roof condition is required.";
      if (!surveyData.siteAccess) nextErrors.siteAccess = "Site access is required.";
      if (!surveyData.existingElectricalLoad) nextErrors.existingElectricalLoad = "Electrical load is required.";
      if (!surveyData.mainDistributionBoardLocation.trim()) nextErrors.mainDistributionBoardLocation = "DB location is required.";
      if (!surveyData.earthingAvailable) nextErrors.earthingAvailable = "Earthing selection is required.";
      if (!surveyData.phaseType) nextErrors.phaseType = "Phase type is required.";
      if (!surveyData.recommendedPanelBrand) nextErrors.recommendedPanelBrand = "Panel brand is required.";
      if (!surveyData.recommendedInverterBrand) nextErrors.recommendedInverterBrand = "Inverter brand is required.";
      if (!surveyData.availableRoofArea) nextErrors.availableRoofArea = "Available roof area is required.";
      if (!surveyData.usableRoofArea) nextErrors.usableRoofArea = "Usable roof area is required.";
    }

    if (step === 2) {
      if (!surveyData.latitude || !surveyData.longitude) nextErrors.coordinates = "GPS coordinates are required.";
      if (!surveyData.locationName.trim()) nextErrors.locationName = "Location name is required.";
    }

    if (step === 3) {
      if (!photos.length) nextErrors.photos = "At least one site photo is required.";
    }

    setValidationErrors((prev) => ({ ...prev, ...nextErrors }));
    return Object.keys(nextErrors).length === 0;
  }, [photos.length, surveyData]);

  const goStep = useCallback((direction) => {
    if (direction > 0 && !validateStep(currentStep)) return;
    setCurrentStep((prev) => Math.max(1, Math.min(3, prev + direction)));
    window.scrollTo({ top: 0, behavior: "smooth" });
  }, [currentStep, validateStep]);

  const surveySummary = useMemo(() => {
    const lines = [
      "Site Survey Summary",
      `Roof Type: ${surveyData.roofType || "-"}`,
      `Roof Material: ${surveyData.roofMaterial || "-"}`,
      `Roof Condition: ${surveyData.roofCondition || "-"}`,
      `Shading Issues: ${surveyData.shadingIssues.length ? surveyData.shadingIssues.join(", ") : "-"}`,
      `Site Access: ${surveyData.siteAccess || "-"}`,
      `Existing Electrical Load (kW): ${surveyData.existingElectricalLoad || "-"}`,
      `Main Distribution Board Location: ${surveyData.mainDistributionBoardLocation || "-"}`,
      `Earthing Available: ${surveyData.earthingAvailable || "-"}`,
      `Phase Type: ${surveyData.phaseType || "-"}`,
      `Recommended Panel Brand: ${surveyData.recommendedPanelBrand || "-"}`,
      `Recommended Inverter Brand: ${surveyData.recommendedInverterBrand || "-"}`,
      `Inverter Type: ${surveyData.inverterType || "-"}`,
      `Available Roof Area (sq ft): ${surveyData.availableRoofArea || "-"}`,
      `Usable Roof Area (sq ft): ${surveyData.usableRoofArea || "-"}`,
      `Distance from Roof to DB (meters): ${surveyData.distanceFromRoofToDb || "-"}`,
      `Customer Expectations: ${surveyData.customerExpectations || "-"}`,
      `Special Requirements: ${surveyData.specialRequirements || "-"}`,
      `Challenges/Concerns: ${surveyData.challengesConcerns || "-"}`,
      `Coordinates: ${surveyData.latitude || "-"}, ${surveyData.longitude || "-"}`,
    ];

    if (surveyData.remarks.trim()) {
      lines.push(`Additional Notes: ${surveyData.remarks.trim()}`);
    }

    return lines.join("\n");
  }, [surveyData]);

  const handleSubmit = useCallback(async () => {
    if (!validateStep(1) || !validateStep(2) || !validateStep(3)) {
      setCurrentStep((prev) => (prev > 1 ? prev : 1));
      setError("Please complete all required survey fields before submitting.");
      return;
    }

    setSaving(true);
    setError("");

    try {
      const now = new Date();
      const formData = new FormData();
      const displayName = leadName || surveyData.locationName.trim() || "Site Survey";

      formData.append("latitude", surveyData.latitude);
      formData.append("longitude", surveyData.longitude);
      formData.append("locationName", surveyData.locationName.trim() || displayName);
      formData.append("isLeadCreated", "other");
      formData.append("visitDate", now.toISOString().split("T")[0]);
      formData.append("visitTime", now.toTimeString().slice(0, 5));
      formData.append("visitStatus", "Completed");
      formData.append("remarks", surveySummary);

      const contactName = getLeadFullName(lead);
      if (contactName) formData.append("contactPerson", contactName);
      if (lead?.phone) formData.append("phone", lead.phone);
      if (lead?.email) formData.append("email", lead.email);
      if (lead?.address) formData.append("address", lead.address);

      photos.forEach((photo) => {
        formData.append("photos", photo.file);
      });

      const response = await fetch(`${BASE_URL}/visit`, {
        method: "POST",
        headers: { Authorization: `Bearer ${getToken()}` },
        body: formData,
      });
      const payload = await response.json();

      if (!response.ok) {
        throw new Error(payload?.message || `HTTP ${response.status}`);
      }

      const visitResult = payload?.result ?? payload?.data ?? payload;
      const visitData = visitResult?.visit ?? visitResult;
      setSubmittedVisit(visitData);
      if (onSave) onSave(visitData);
      setSuccessOpen(true);
    } catch (submitError) {
      setError(submitError.message || "Failed to save site survey.");
    } finally {
      setSaving(false);
    }
  }, [lead, leadName, onSave, photos, surveyData, surveySummary, validateStep]);

  const closeSuccess = useCallback(() => {
    setSuccessOpen(false);
    if (onClose) {
      onClose(submittedVisit);
      return;
    }
    navigate(-1);
  }, [navigate, onClose, submittedVisit]);

  const stepMeta = [
    { key: 1, label: "General" },
    { key: 2, label: "GPS" },
    { key: 3, label: "Photos" },
  ];

  const infoItems = [
    { icon: <Phone sx={{ fontSize: 14 }} />, bg: "#e8f5e9", color: "#43a047", text: lead?.phone || "No phone" },
    { icon: <Email sx={{ fontSize: 14 }} />, bg: "#e3f2fd", color: "#1e88e5", text: lead?.email || "No email" },
    { icon: <LocationOn sx={{ fontSize: 14 }} />, bg: "#fce4ec", color: "#e53935", text: lead?.address || lead?.city || "No address" },
    { icon: <Tag sx={{ fontSize: 14 }} />, bg: "#f3e5f5", color: "#8e24aa", text: lead?.pincode || "No pincode" },
    { icon: <WhatsApp sx={{ fontSize: 14 }} />, bg: "#e8f5e9", color: "#25d366", text: "WhatsApp" },
  ];

  const renderRadioPills = (field, options) => (
    <Box sx={{ display: "flex", flexWrap: "wrap", gap: 1 }}>
      {options.map((option) => {
        const selected = surveyData[field] === option;
        return (
          <Button
            key={option}
            variant="outlined"
            onClick={() => updateField(field, option)}
            sx={{
              borderRadius: 2,
              px: 1.5,
              py: 0.7,
              borderColor: selected ? PRIMARY : "#ddd",
              color: selected ? PRIMARY : TEXT_SUB,
              bgcolor: selected ? alpha(PRIMARY, 0.08) : "#fafafa",
              fontWeight: selected ? 700 : 500,
              textTransform: "none",
              "&:hover": { borderColor: PRIMARY, bgcolor: alpha(PRIMARY, 0.08) },
            }}
          >
            {option}
          </Button>
        );
      })}
    </Box>
  );

  const renderCheckboxPills = (field, options) => (
    <Box sx={{ display: "flex", flexWrap: "wrap", gap: 1 }}>
      {options.map((option) => {
        const selected = surveyData[field].includes(option);
        return (
          <Button
            key={option}
            variant="outlined"
            onClick={() => toggleCheckboxValue(field, option)}
            sx={{
              borderRadius: 2,
              px: 1.5,
              py: 0.7,
              borderColor: selected ? PRIMARY : "#ddd",
              color: selected ? PRIMARY : TEXT_SUB,
              bgcolor: selected ? alpha(PRIMARY, 0.08) : "#fafafa",
              fontWeight: selected ? 700 : 500,
              textTransform: "none",
              "&:hover": { borderColor: PRIMARY, bgcolor: alpha(PRIMARY, 0.08) },
            }}
          >
            {option}
          </Button>
        );
      })}
    </Box>
  );

  return (
    <Box sx={{ minHeight: "100vh", bgcolor: SURFACE_ALT, color: TEXT, pb: 12 }}>
      <input
        ref={fileInputRef}
        type="file"
        accept="image/*"
        multiple
        onChange={handleFileChange}
        style={{ display: "none" }}
      />

      <Paper
        elevation={0}
        sx={{
          borderRadius: 0,
          borderBottom: `1px solid ${BORDER}`,
          px: { xs: 2, md: 2.5 },
          py: 1.25,
          position: "sticky",
          top: 0,
          zIndex: 20,
        }}
      >
        <Stack direction="row" alignItems="center" justifyContent="space-between" spacing={2}>
          <Stack direction="row" spacing={1.5} alignItems="center">
            <Box
              sx={{
                width: 34,
                height: 34,
                borderRadius: 1.5,
                bgcolor: PRIMARY,
                color: "#fff",
                display: "grid",
                placeItems: "center",
                fontSize: "0.82rem",
                fontWeight: 800,
                textTransform: "lowercase",
              }}
            >
              {avatarLabel}
            </Box>
            <Box>
              <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap">
                <Typography sx={{ fontSize: "0.95rem", fontWeight: 700, color: TEXT }}>
                  Update Site Survey
                </Typography>
                <Chip
                  label="EDITING"
                  size="small"
                  sx={{
                    height: 22,
                    bgcolor: "#fff7ed",
                    color: PRIMARY,
                    border: "1px solid #fdd8b4",
                    fontSize: "0.68rem",
                    fontWeight: 700,
                    borderRadius: 999,
                  }}
                />
              </Stack>
              <Typography sx={{ fontSize: "0.78rem", color: TEXT_MUTED }}>
                {leadName || "Survey draft"}
              </Typography>
            </Box>
          </Stack>

          <Button
            variant="outlined"
            startIcon={<ArrowBack sx={{ fontSize: 14 }} />}
            onClick={() => (onClose ? onClose() : navigate(-1))}
            sx={{
              borderRadius: 1.5,
              px: 1.75,
              py: 0.7,
              borderColor: "#ddd",
              color: TEXT_SUB,
              bgcolor: "#f5f5f5",
              fontWeight: 600,
              textTransform: "none",
              "&:hover": { bgcolor: "#ececec", borderColor: "#ddd" },
            }}
          >
            Back
          </Button>
        </Stack>
      </Paper>

      <Paper elevation={0} sx={{ borderRadius: 0, borderBottom: `1px solid ${BORDER}`, px: { xs: 2, md: 2.5 }, py: 1 }}>
        <Stack direction="row" spacing={2} useFlexGap flexWrap="wrap">
          {infoItems.map((item) => (
            <Stack key={item.text} direction="row" spacing={0.75} alignItems="center">
              <Box
                sx={{
                  width: 26,
                  height: 26,
                  borderRadius: "50%",
                  bgcolor: item.bg,
                  color: item.color,
                  display: "grid",
                  placeItems: "center",
                }}
              >
                {item.icon}
              </Box>
              <Typography sx={{ fontSize: "0.8rem", color: TEXT_SUB }}>{item.text}</Typography>
            </Stack>
          ))}
        </Stack>
      </Paper>

      <Paper elevation={0} sx={{ borderRadius: 0, borderBottom: `1px solid ${BORDER}`, px: { xs: 2, md: 2.5 }, py: 2 }}>
        <Stack direction="row" alignItems="center" justifyContent="center" spacing={1.5} sx={{ maxWidth: 560, mx: "auto" }}>
          {stepMeta.map((step, index) => (
            <React.Fragment key={step.key}>
              <Stack spacing={0.75} alignItems="center" sx={{ zIndex: 1 }}>
                <Box
                  sx={{
                    width: 32,
                    height: 32,
                    borderRadius: "50%",
                    border: `2px solid ${step.key < currentStep ? PRIMARY : step.key === currentStep ? PRIMARY : "#ddd"}`,
                    bgcolor: step.key < currentStep ? PRIMARY : "#fff",
                    color: step.key < currentStep ? "#fff" : step.key === currentStep ? PRIMARY : "#aaa",
                    display: "grid",
                    placeItems: "center",
                    fontSize: "0.82rem",
                    fontWeight: 700,
                    boxShadow: step.key === currentStep ? `0 0 0 4px ${alpha(PRIMARY, 0.14)}` : "none",
                  }}
                >
                  {step.key}
                </Box>
                <Typography sx={{ fontSize: "0.72rem", color: step.key <= currentStep ? PRIMARY : "#aaa", fontWeight: 600 }}>
                  {step.label}
                </Typography>
              </Stack>
              {index < stepMeta.length - 1 ? (
                <Box sx={{ flex: 1, height: 2, bgcolor: index + 1 < currentStep ? PRIMARY : BORDER, mb: 3 }} />
              ) : null}
            </React.Fragment>
          ))}
        </Stack>
      </Paper>

      <Box sx={{ px: 2, py: 2, maxWidth: 980, mx: "auto" }}>
        {error ? (
          <Alert severity="error" sx={{ mb: 2.5, borderRadius: 2 }} onClose={() => setError("")}>
            {error}
          </Alert>
        ) : null}

        {currentStep === 1 ? (
          <Paper sx={{ borderRadius: 2.5, border: `1px solid ${BORDER}`, overflow: "hidden" }}>
            <Stack direction="row" alignItems="center" justifyContent="space-between" sx={{ px: 2.25, py: 1.5, borderBottom: `1px solid #f0f0f0` }}>
              <Stack direction="row" spacing={1} alignItems="center">
                <Box sx={{ width: 26, height: 26, borderRadius: 1.5, bgcolor: "#fff5ef", color: PRIMARY, display: "grid", placeItems: "center" }}>
                  <HomeWorkOutlined sx={{ fontSize: 15 }} />
                </Box>
                <Typography sx={{ fontSize: "0.9rem", fontWeight: 700, color: TEXT }}>General</Typography>
              </Stack>
              <Chip label="31 fields" size="small" sx={{ height: 22, bgcolor: "#f5f5f5", color: TEXT_MUTED, fontSize: "0.7rem" }} />
            </Stack>

            <Box sx={{ p: 2.25 }}>
              <Grid container spacing={2.25}>
                <Grid item xs={12} sm={6}>
                  <TextField
                    select
                    SelectProps={{ native: true }}
                    label="Roof Type *"
                    value={surveyData.roofType}
                    onChange={(event) => updateField("roofType", event.target.value)}
                    fullWidth
                    error={Boolean(validationErrors.roofType)}
                    helperText={validationErrors.roofType}
                  >
                    <option value="">Select Roof Type</option>
                    {ROOF_TYPES.map((option) => <option key={option} value={option}>{option}</option>)}
                  </TextField>
                </Grid>
                <Grid item xs={12} sm={6}>
                  <TextField
                    select
                    SelectProps={{ native: true }}
                    label="Roof Material *"
                    value={surveyData.roofMaterial}
                    onChange={(event) => updateField("roofMaterial", event.target.value)}
                    fullWidth
                    error={Boolean(validationErrors.roofMaterial)}
                    helperText={validationErrors.roofMaterial}
                  >
                    <option value="">Select Roof Material</option>
                    {ROOF_MATERIALS.map((option) => <option key={option} value={option}>{option}</option>)}
                  </TextField>
                </Grid>

                <Grid item xs={12} sm={6}>
                  <Typography sx={{ fontSize: "0.8rem", fontWeight: 600, color: TEXT_SUB, mb: 0.8 }}>Roof Condition *</Typography>
                  {renderRadioPills("roofCondition", ROOF_CONDITIONS)}
                  {validationErrors.roofCondition ? <FormHelperText error>{validationErrors.roofCondition}</FormHelperText> : null}
                </Grid>
                <Grid item xs={12} sm={6}>
                  <Typography sx={{ fontSize: "0.8rem", fontWeight: 600, color: TEXT_SUB, mb: 0.8 }}>Shading Issues</Typography>
                  {renderCheckboxPills("shadingIssues", SHADING_OPTIONS)}
                </Grid>

                <Grid item xs={12} sm={6}>
                  <Typography sx={{ fontSize: "0.8rem", fontWeight: 600, color: TEXT_SUB, mb: 0.8 }}>Site Access *</Typography>
                  {renderRadioPills("siteAccess", SITE_ACCESS_OPTIONS)}
                  {validationErrors.siteAccess ? <FormHelperText error>{validationErrors.siteAccess}</FormHelperText> : null}
                </Grid>
                <Grid item xs={12} sm={6}>
                  <TextField
                    label="Existing Electrical Load (kW) *"
                    type="number"
                    value={surveyData.existingElectricalLoad}
                    onChange={(event) => updateField("existingElectricalLoad", event.target.value)}
                    fullWidth
                    error={Boolean(validationErrors.existingElectricalLoad)}
                    helperText={validationErrors.existingElectricalLoad}
                  />
                </Grid>

                <Grid item xs={12} sm={6}>
                  <TextField
                    label="Main Distribution Board Location *"
                    value={surveyData.mainDistributionBoardLocation}
                    onChange={(event) => updateField("mainDistributionBoardLocation", event.target.value)}
                    fullWidth
                    error={Boolean(validationErrors.mainDistributionBoardLocation)}
                    helperText={validationErrors.mainDistributionBoardLocation}
                  />
                </Grid>
                <Grid item xs={12} sm={6}>
                  <Typography sx={{ fontSize: "0.8rem", fontWeight: 600, color: TEXT_SUB, mb: 0.8 }}>Earthing Available *</Typography>
                  {renderRadioPills("earthingAvailable", EARTHING_OPTIONS)}
                  {validationErrors.earthingAvailable ? <FormHelperText error>{validationErrors.earthingAvailable}</FormHelperText> : null}
                </Grid>

                <Grid item xs={12} sm={6}>
                  <Typography sx={{ fontSize: "0.8rem", fontWeight: 600, color: TEXT_SUB, mb: 0.8 }}>Phase Type *</Typography>
                  {renderRadioPills("phaseType", PHASE_OPTIONS)}
                  {validationErrors.phaseType ? <FormHelperText error>{validationErrors.phaseType}</FormHelperText> : null}
                </Grid>
                <Grid item xs={12} sm={6}>
                  <TextField
                    select
                    SelectProps={{ native: true }}
                    label="Recommended Panel Brand *"
                    value={surveyData.recommendedPanelBrand}
                    onChange={(event) => updateField("recommendedPanelBrand", event.target.value)}
                    fullWidth
                    error={Boolean(validationErrors.recommendedPanelBrand)}
                    helperText={validationErrors.recommendedPanelBrand}
                  >
                    <option value="">Select Recommended Panel Brand</option>
                    {PANEL_BRANDS.map((option) => <option key={option} value={option}>{option}</option>)}
                  </TextField>
                </Grid>

                <Grid item xs={12} sm={6}>
                  <TextField
                    select
                    SelectProps={{ native: true }}
                    label="Recommended Inverter Brand *"
                    value={surveyData.recommendedInverterBrand}
                    onChange={(event) => updateField("recommendedInverterBrand", event.target.value)}
                    fullWidth
                    error={Boolean(validationErrors.recommendedInverterBrand)}
                    helperText={validationErrors.recommendedInverterBrand}
                  >
                    <option value="">Select Recommended Inverter Brand</option>
                    {INVERTER_BRANDS.map((option) => <option key={option} value={option}>{option}</option>)}
                  </TextField>
                </Grid>
                <Grid item xs={12} sm={6}>
                  <Typography sx={{ fontSize: "0.8rem", fontWeight: 600, color: TEXT_SUB, mb: 0.8 }}>Inverter Type</Typography>
                  {renderRadioPills("inverterType", INVERTER_TYPES)}
                </Grid>

                <Grid item xs={12} sm={6}>
                  <TextField
                    label="Available Roof Area (sq ft) *"
                    type="number"
                    value={surveyData.availableRoofArea}
                    onChange={(event) => updateField("availableRoofArea", event.target.value)}
                    fullWidth
                    error={Boolean(validationErrors.availableRoofArea)}
                    helperText={validationErrors.availableRoofArea}
                  />
                </Grid>
                <Grid item xs={12} sm={6}>
                  <TextField
                    label="Usable Roof Area (sq ft) *"
                    type="number"
                    value={surveyData.usableRoofArea}
                    onChange={(event) => updateField("usableRoofArea", event.target.value)}
                    fullWidth
                    error={Boolean(validationErrors.usableRoofArea)}
                    helperText={validationErrors.usableRoofArea}
                  />
                </Grid>
                <Grid item xs={12}>
                  <TextField
                    label="Distance from Roof to DB (meters)"
                    type="number"
                    value={surveyData.distanceFromRoofToDb}
                    onChange={(event) => updateField("distanceFromRoofToDb", event.target.value)}
                    fullWidth
                  />
                </Grid>

                <Grid item xs={12}>
                  <TextField
                    label="Customer Expectations"
                    value={surveyData.customerExpectations}
                    onChange={(event) => updateField("customerExpectations", event.target.value)}
                    multiline
                    minRows={3}
                    fullWidth
                  />
                </Grid>
                <Grid item xs={12}>
                  <TextField
                    label="Special Requirements"
                    value={surveyData.specialRequirements}
                    onChange={(event) => updateField("specialRequirements", event.target.value)}
                    multiline
                    minRows={3}
                    fullWidth
                  />
                </Grid>
                <Grid item xs={12}>
                  <TextField
                    label="Challenges / Concerns"
                    value={surveyData.challengesConcerns}
                    onChange={(event) => updateField("challengesConcerns", event.target.value)}
                    multiline
                    minRows={3}
                    fullWidth
                  />
                </Grid>
              </Grid>
            </Box>
          </Paper>
        ) : null}

        {currentStep === 2 ? (
          <Paper sx={{ borderRadius: 2.5, border: `1px solid ${BORDER}`, overflow: "hidden" }}>
            <Stack direction="row" alignItems="center" justifyContent="space-between" sx={{ px: 2.25, py: 1.5, borderBottom: `1px solid #f0f0f0` }}>
              <Stack direction="row" spacing={1} alignItems="center">
                <Box sx={{ width: 26, height: 26, borderRadius: 1.5, bgcolor: "#fff5ef", color: PRIMARY, display: "grid", placeItems: "center" }}>
                  <LocationOn sx={{ fontSize: 15 }} />
                </Box>
                <Typography sx={{ fontSize: "0.9rem", fontWeight: 700, color: TEXT }}>GPS Coordinates</Typography>
              </Stack>
            </Stack>

            <Box sx={{ p: 2.25 }}>
              <Box sx={{ width: "100%", height: 260, borderRadius: 2, overflow: "hidden", border: `1px solid #ddd`, bgcolor: "#e8e0d5" }}>
                <MapContainer center={mapCenter} zoom={surveyData.latitude ? 16 : 5} style={{ height: "100%", width: "100%" }}>
                  <TileLayer
                    attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'
                    url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
                  />
                  <MapViewportSync center={mapCenter} />
                  <MapClickHandler onPick={handleMapPick} />
                  {surveyData.latitude && surveyData.longitude ? (
                    <Marker
                      position={[Number(surveyData.latitude), Number(surveyData.longitude)]}
                      draggable
                      eventHandlers={{
                        dragend: async (event) => {
                          const marker = event.target;
                          const next = marker.getLatLng();
                          await handleMapPick(next.lat, next.lng);
                        },
                      }}
                    />
                  ) : null}
                </MapContainer>
              </Box>
              <Typography sx={{ textAlign: "center", fontSize: "0.72rem", color: TEXT_MUTED, mt: 0.8 }}>
                Click on the map or drag the pin to set the exact location
              </Typography>

              <Box sx={{ textAlign: "center", fontSize: "0.75rem", color: "#aaa", my: 1.75, position: "relative" }}>
                <Box sx={{ position: "absolute", left: 0, right: 0, top: "50%", height: 1, bgcolor: BORDER, zIndex: 0 }} />
                <Box component="span" sx={{ px: 1.5, bgcolor: SURFACE, position: "relative", zIndex: 1 }}>
                  OR USE DEVICE GPS
                </Box>
              </Box>

              <Button
                variant="outlined"
                startIcon={locationLoading ? <CircularProgress size={16} sx={{ color: PRIMARY }} /> : <MyLocation sx={{ fontSize: 16 }} />}
                onClick={() => getCurrentLocation()}
                sx={{
                  borderRadius: 2,
                  px: 2,
                  py: 1,
                  borderColor: PRIMARY,
                  color: PRIMARY,
                  fontWeight: 700,
                  textTransform: "none",
                  "&:hover": { borderColor: PRIMARY, bgcolor: "#fff5ef" },
                }}
              >
                {locationLoading ? `Getting location${locationAttempts ? ` (${locationAttempts + 1}/3)` : ""}` : "Get Current Location"}
              </Button>

              <Grid container spacing={1.75} sx={{ mt: 0.25 }}>
                <Grid item xs={12} sm={6}>
                  <TextField
                    label="Latitude"
                    value={surveyData.latitude}
                    onChange={(event) => updateField("latitude", event.target.value)}
                    fullWidth
                  />
                </Grid>
                <Grid item xs={12} sm={6}>
                  <TextField
                    label="Longitude"
                    value={surveyData.longitude}
                    onChange={(event) => updateField("longitude", event.target.value)}
                    fullWidth
                  />
                </Grid>
                <Grid item xs={12}>
                  <TextField
                    label="Location Name *"
                    value={surveyData.locationName}
                    onChange={(event) => updateField("locationName", event.target.value)}
                    fullWidth
                    error={Boolean(validationErrors.locationName)}
                    helperText={validationErrors.locationName}
                  />
                </Grid>
              </Grid>

              {validationErrors.coordinates ? <FormHelperText error sx={{ mt: 1 }}>{validationErrors.coordinates}</FormHelperText> : null}
            </Box>
          </Paper>
        ) : null}

        {currentStep === 3 ? (
          <Paper sx={{ borderRadius: 2.5, border: `1px solid ${BORDER}`, overflow: "hidden" }}>
            <Stack direction="row" alignItems="center" justifyContent="space-between" sx={{ px: 2.25, py: 1.5, borderBottom: `1px solid #f0f0f0` }}>
              <Stack direction="row" spacing={1} alignItems="center">
                <Box sx={{ width: 26, height: 26, borderRadius: 1.5, bgcolor: "#fff5ef", color: PRIMARY, display: "grid", placeItems: "center" }}>
                  <CameraAlt sx={{ fontSize: 15 }} />
                </Box>
                <Typography sx={{ fontSize: "0.9rem", fontWeight: 700, color: TEXT }}>Site Photos</Typography>
              </Stack>
            </Stack>

            <Box sx={{ p: 2.25 }}>
              <Typography sx={{ fontSize: "0.8rem", fontWeight: 600, color: TEXT_SUB, mb: 1.25 }}>
                Upload Site Photos
              </Typography>

              <Box
                onClick={() => fileInputRef.current?.click()}
                onDragOver={(event) => event.preventDefault()}
                onDrop={(event) => {
                  event.preventDefault();
                  addFiles(event.dataTransfer.files);
                }}
                sx={{
                  border: "2px dashed #d0d0d0",
                  borderRadius: 2.5,
                  px: 2,
                  py: 5,
                  textAlign: "center",
                  cursor: "pointer",
                  bgcolor: "#fafafa",
                  transition: "all 0.2s ease",
                  "&:hover": {
                    borderColor: PRIMARY,
                    bgcolor: "#fff5ef",
                  },
                }}
              >
                <CloudUploadOutlined sx={{ fontSize: 32, color: alpha(PRIMARY, 0.7), mb: 1 }} />
                <Typography sx={{ fontSize: "0.88rem", color: TEXT_SUB }}>
                  Drag and drop photos or <Box component="span" sx={{ color: PRIMARY, fontWeight: 700 }}>Browse</Box>
                </Typography>
                <Typography sx={{ fontSize: "0.72rem", color: "#bbb", mt: 0.75 }}>
                  Supports JPG, PNG, WEBP
                </Typography>
              </Box>

              {validationErrors.photos ? <FormHelperText error sx={{ mt: 1 }}>{validationErrors.photos}</FormHelperText> : null}

              {photos.length ? (
                <Stack direction="row" spacing={1.25} useFlexGap flexWrap="wrap" sx={{ mt: 2 }}>
                  {photos.map((photo) => (
                    <UploadPreview key={photo.id} photo={photo} onRemove={removePhoto} />
                  ))}
                </Stack>
              ) : null}

              <TextField
                label="Additional Notes"
                value={surveyData.remarks}
                onChange={(event) => updateField("remarks", event.target.value)}
                multiline
                minRows={4}
                fullWidth
                sx={{ mt: 2.25 }}
              />
            </Box>
          </Paper>
        ) : null}
      </Box>

      <Paper
        elevation={0}
        sx={{
          position: "fixed",
          left: 0,
          right: 0,
          bottom: 0,
          borderTop: `1px solid ${BORDER}`,
          px: { xs: 2, md: 2.5 },
          py: 1.5,
          zIndex: 20,
        }}
      >
        <Stack direction="row" alignItems="center" justifyContent="space-between" spacing={2} flexWrap="wrap">
          <Stack direction="row" spacing={1.25} flexWrap="wrap">
            {currentStep === 1 ? (
              <Button
                variant="outlined"
                onClick={() => {
                  if (onClose) onClose();
                  else navigate(-1);
                }}
                sx={{
                  borderRadius: 1.75,
                  px: 2,
                  py: 0.95,
                  borderColor: "#ddd",
                  color: TEXT_SUB,
                  fontWeight: 700,
                  textTransform: "none",
                }}
              >
                Cancel
              </Button>
            ) : (
              <Button
                variant="outlined"
                startIcon={<ArrowBack sx={{ fontSize: 14 }} />}
                onClick={() => goStep(-1)}
                sx={{
                  borderRadius: 1.75,
                  px: 2,
                  py: 0.95,
                  borderColor: "#ddd",
                  color: TEXT_SUB,
                  fontWeight: 700,
                  textTransform: "none",
                }}
              >
                Previous
              </Button>
            )}
          </Stack>

          <Stack direction="row" alignItems="center" spacing={2}>
            <Typography sx={{ fontSize: "0.78rem", color: TEXT_MUTED }}>
              Step {currentStep} of 3
            </Typography>
            {currentStep < 3 ? (
              <Button
                variant="contained"
                endIcon={<ArrowForward sx={{ fontSize: 14 }} />}
                onClick={() => goStep(1)}
                sx={{
                  borderRadius: 1.75,
                  px: 2.25,
                  py: 0.95,
                  bgcolor: PRIMARY,
                  fontWeight: 700,
                  textTransform: "none",
                  "&:hover": { bgcolor: PRIMARY_DARK },
                }}
              >
                Next
              </Button>
            ) : (
              <Button
                variant="contained"
                startIcon={saving ? <CircularProgress size={18} color="inherit" /> : <CheckCircle sx={{ fontSize: 16 }} />}
                disabled={saving}
                onClick={handleSubmit}
                sx={{
                  borderRadius: 1.75,
                  px: 2.25,
                  py: 0.95,
                  bgcolor: PRIMARY,
                  fontWeight: 700,
                  textTransform: "none",
                  "&:hover": { bgcolor: PRIMARY_DARK },
                  "&.Mui-disabled": { bgcolor: alpha(PRIMARY, 0.55), color: "#fff" },
                }}
              >
                {saving ? "Saving..." : "Update Survey"}
              </Button>
            )}
          </Stack>
        </Stack>
      </Paper>

      <SuccessDialog open={successOpen} onClose={closeSuccess} leadName={leadName} />
    </Box>
  );
}
